return "\nservant_advance 3501 {\n    request {\n        servantid 0 : integer\n    }\n    response {\n        result 0 : integer\n        consumes 1 : *consumeids\n    }\n}\n\n#角色一键装备(装备魂武,零件)\nservant_equip_one_key 3502 {\n    request {\n        .component{\n            pos 0 : integer\n            entityid 1 : integer\n        }\n        .servantInfo{\n            servantid 0 : integer\n            weaponEntityid 1 : integer\n            componentList 2 : *component\n        }\n        list 0 : *servantInfo\n    }\n    response {\n        .component{\n            pos 0 : integer\n            result 1 : integer\n        }\n        .resultInfo{\n            servantid 0 : integer\n            weaponResult 1 : integer\n            componentResult 2 : *component\n        }\n        result 0 : integer\n        list 1 : *resultInfo\n    }\n}\n\n#角色一键强化(强化角色等级,魂武等级,零件等级,突破等级)\nservant_strengthen_one_key 3503 {\n    request {\n        servantid       0 : integer\n        strengthpoint   1 : integer     #强化角色等级消耗的科技点\n        coreRank        2 : integer     #目标突破等级\n        weaponLevel     3 : integer     #目标魂武等级\n        component1      4 : *integer    #强化第一个芯片等级需要消耗的芯片材料\n        component2      5 : *integer    #强化第二个芯片等级需要消耗的芯片材料\n        component3      6 : *integer    #强化第三个芯片等级需要消耗的芯片材料\n    }\n    response {\n        .component{\n            entityid 0 : integer\n            component 1 : item_component\n        }\n        result 0 : integer\n        strengthpoint 1 : integer\n        core 2 : core\n        weaponLevel 3 : integer\n        componentList 4 : *component\n        costgold 5 : integer            #消耗的金币\n    }\n}\n\n#角色吞噬魂器\nservant_eat_horcrux 3504 {\n    request {\n        servantid 0 : integer\n        horcruxid 1 : integer #被吞噬魂器id\n        materials 2 : *integer #材料魂器\n        pos 3 : integer #吞噬位置\n    }\n    response {\n        result 0 : integer # 1 成功 2 失败,学员不存在 3 失败，魂器不存在 4 失败，魂器锁定 5 失败，配置错误 6 失败，魂器等级或者星级不满足要求 7 失败，材料不足 8 有新技能未二次确认 9 失败，魂器属性和学员属性不匹配 10 失败，指定的魂器位置未解锁 11 失败，异构学员吞噬限制\n        servant_horcrux 1 : *servant_horcrux\n        cost_items 2 : *consumeids\n        horcrux 3 : item #魂器\n    }\n}\n\n#二次确认角色吞噬魂器的技能\nservant_confirm_newskill 3505 {\n    request {\n        servantid 0 : integer\n        pos 1 : integer #魂器位置\n        replace 2 : boolean #是否替换\n    }\n    response {\n        result 0 : integer # 1 成功 2 失败,学员不存在 3 失败，不存在需要二次确认的技能\n        servant_horcrux 1 : *servant_horcrux\n        cost_items 2 : *consumeids\n        horcrux 3 : item #魂器\n        old_horcrux    4 : item #原魂器\n    }\n}\n\n# 拆卸吞噬的魂器\nservant_disassemble_horcrux 3506 {\n    request {\n        servantid 0 : integer\n        pos 1 : integer #魂器位置\n    }\n    response {\n        result 0 : integer # 1 成功 2 失败,学员不存在\n        servant_horcrux 1 : *servant_horcrux\n        cost_items 2 : *consumeids\n        horcrux 3 : item\n    }\n}\n\n#共振点排行榜\nget_breakout_star_rank 3507 {\n    request {\n        start 0 : integer   #起始的index(1是第一个)\n        count 1 : integer   #数量\n}\n    response {\n         data 0 : *rankdata  #排名列表\n         selfrank 1 : integer  #玩家自身排名， start==1时,该值有效\n    }\n}\n"
